      "content": "/**\n * dsh-computer-use —— Computer Use 插件：给 harness-desktop 增加\"虚拟鼠标真人操作\"。\n *\n * 工具集（Hermes 风格，模型友好）：\n *   screen_observe          看屏幕：AX 编号树 + 坐标 / 原生直读 / 视觉观察者\n *   screen_zoom             区域截图直读（≤500px JPEG，细节放大看）\n *   computer_click          点击（element 编号 或 x/y 坐标）\n *   computer_double_click   双击\n *   computer_right_click    右键\n *   computer_type           文本输入\n *   computer_key            按键 / 快捷键\n *   computer_scroll         滚动\n *   computer_drag           拖拽\n *   computer_wait           等待 / 轮询间隔\n *   app_list                列出应用\n *   app_launch              启动应用\n *\n * 视觉能力（原生接入）：\n *   - mode=\"native\"：截图经 attachments 持久化后以图片块返回，主对话模型\n *     （如 deepseek-v4-flash-vision-exp）直接看图 —— 零外部 API、零额外 key。\n *   - mode=\"vision\"：DeepSeek 视觉观察者（ctx.llm）结构化描述截图（免 ZHIPU key），\n *     不可用时回退 GLM 免费模型。\n *   - ax：零成本 AX 树；AX 树为空时自动降级 native → vision → ax。\n *\n * 安全设计（P1 已内建，P3 深化）：\n *   - 观察快照 TTL：过期后拒绝动作，必须重新观察（element_token 引擎侧双重校验）\n *   - 动作一律要求先 screen_observe（无快照直接拒绝，杜绝盲操作）\n */\nimport z from '@deepseek-ai/schemastery'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\n\nimport { screenObserve, screenZoom } from './lib/observe.js'\nimport {\n  click, doubleClick, rightClick, typeText, key, scroll, drag, wait, listApps, launchApp,\n} from './lib/actions.js'\nimport { guard } from './lib/guard.js'\nimport { cuaCall, CUA_SESSION } from './lib/cua.js'\n\nexport const name = 'dsh-computer-use'\n\nexport const inject = ['tools', 'approval']\n\n/** 插件配置。 */\nexport const Config = z.object({\n  /** 观察快照的有效期（毫秒）。 */\n  ttlMs: z.number().default(30000),\n  /** screen_observe 最多返回多少编号元素。 */\n  maxElements: z.number().default(500),\n  /** 区域限制：允许操作的应用名白名单（空 = 不限制）。 */\n  allowedApps: z.array(z.string()).default([]),\n  /** 虚拟光标主题 id（空 = 不设置，用引擎默认）。 */\n  cursorTheme: z.string().default('com.dsh.computeruse.rainbow'),\n  /** 原生直读截图策略：auto（PNG 超限额时自动降级 zoom JPEG）/ full（始终原图 PNG）/ compact（始终 ≤500px JPEG）。 */\n  nativeImage: z.union(['auto', 'full', 'compact']).default('auto'),\n  /** Mode D 观察者 provider 路由。 */\n  visionProvider: z.string().default('deepseek-official'),\n  /** Mode D 观察者模型（需声明 image 输入）。 */\n  visionModel: z.string().default('deepseek-v4-flash-vision-exp'),\n})\n\n/** 统一输出 schema：ok + result 文本。 */\nconst OUT = (extra = {}) => ({\n  schema: {\n    type: 'object',\n    additionalProperties: false,\n    properties: {\n      ok: { type: 'boolean', required: true },\n      result: { type: 'string', required: true },\n      ...extra,\n    },\n  },\n  render: (_args, value) => [{ type: 'text', text: value.result }],\n})\n\n/** 图片块输出 schema 段（native 直读工具共用）。 */\nconst IMAGE_FIELD = {\n  image: {\n    type: 'object',\n    additionalProperties: false,\n    properties: {\n      attachmentId: { type: 'string', required: true },\n      mediaType: { type: 'string', enum: ['image/png', 'image/jpeg', 'image/webp', 'image/gif'], required: true },\n      bytes: { type: 'integer', required: true },\n      width: { oneOf: [{ type: 'integer' }, { type: 'null' }] },\n      height: { oneOf: [{ type: 'integer' }, { type: 'null' }] },\n      name: { type: 'string' },\n    },\n  },\n}\n\n/** render：值含 image 时追加图片块（主模型原生直读）。 */\nexport function renderWithImage(_args, value) {\n  if (!value.image) return [{ type: 'text', text: value.result }]\n  return [\n    { type: 'text', text: value.result },\n    {\n      type: 'image',\n      attachment: {\n        attachmentId: value.image.attachmentId,\n        mediaType: value.image.mediaType,\n        bytes: value.image.bytes,\n        width: value.image.width,\n        height: value.image.height,\n        ...value.image.name === undefined ? {} : { name: value.image.name },\n      },\n    },\n  ]\n}\n\n/** 统一的坐标/编号参数块（坐标 = 窗口本地截图像素）。 */\nconst TARGET_PARAMS = {\n  element: {\n    type: 'integer',\n    description: 'screen_observe 输出的元素编号（如 5）。与 x/y 二选一，优先。',\n  },\n  x: {\n    type: 'integer',\n    description: '窗口本地截图像素 x（screen_observe 的截图坐标系，模型所见即所点）。与 element 二选一。',\n  },\n  y: {\n    type: 'integer',\n    description: '窗口本地截图像素 y。',\n  },\n}\n\nexport function apply(ctx, config) {\n  const cfg = {\n    ttlMs: config.ttlMs,\n    maxElements: config.maxElements,\n    allowedApps: Array.isArray(config.allowedApps) ? config.allowedApps : [],\n    cursorTheme: config.cursorTheme,\n    nativeImage: config.nativeImage || 'auto',\n    visionProvider: config.visionProvider || 'deepseek-official',\n    visionModel: config.visionModel || 'deepseek-v4-flash-vision-exp',\n  }\n\n  // 初始化虚拟光标：声明统一会话 + 应用主题（异步，不阻塞插件加载）\n  cuaCall('start_session', { session: CUA_SESSION }).catch(() => undefined)\n  if (cfg.cursorTheme) {\n    cuaCall('set_agent_cursor_theme', { session: CUA_SESSION, theme_id: cfg.cursorTheme })\n      .catch(() => undefined)\n  }\n\n  /** 统一包装：先过安全护栏，再执行实现（exec 透传给需要 route 的实现）。 */\n  const wrap = (toolName, impl) => async (args, exec) => {\n    try {\n      const g = await guard(ctx, cfg, toolName, args, exec)\n      if (!g.ok) return { ok: false, result: `✗ ${g.reason}` }\n      return await impl(args, cfg, exec)\n    } catch (err) {\n      return { ok: false, result: `✗ ${err.message}` }\n    }\n  }\n\n  ctx.tools.register(defineTool({\n    name: 'screen_observe',\n    description:\n      '观察屏幕：对目标窗口生成\"编号 + 控件 + 坐标\"的界面树（AX 语义，零视觉 token 成本）。' +\n      '操作电脑前必须先调用本工具取得快照；之后用 computer_click(element=[编号]) 或 computer_click(x=,y=) 操作（坐标为窗口本地截图像素）。' +\n      'mode 选择：ax（默认，零成本树）/ vision（DeepSeek 视觉观察者结构化描述，免 ZHIPU key）/ native（截图直读，当前对话模型直接看图，需模型支持图片输入）。' +\n      'AX 树无法解析（游戏/Canvas/Electron）时自动降级：native（若当前模型支持图片）→ vision → ax。' +\n      '快照默认 30 秒过期，过期后需重新观察。',\n    parameters: {\n      window: {\n        type: 'string',\n        description: '可选：目标窗口，传 pid 数字或标题子串（如 \"访达\"）。缺省选最前窗口。',\n      },\n      mode: {\n        type: 'string',\n        enum: ['ax', 'vision', 'native'],\n        description: 'ax（默认）= 零成本的界面树；vision = 视觉观察者描述；native = 截图直读（模型直接看图）。',\n      },\n      query: {\n        type: 'string',\n        description: '可选：按控件标签过滤界面树（如 \"提交\"）。',\n      },\n      maxElements: {\n        type: 'integer',\n        description: '可选：最多返回多少个编号元素（防上下文爆炸）。',\n      },\n    },\n    output: { ...OUT({\n      window: { type: 'object', additionalProperties: false, properties: {\n        pid: { type: 'integer' }, windowId: { type: 'integer' },\n        app: { type: 'string' }, title: { type: 'string' },\n      } },\n      elementCount: { type: 'integer' },\n      mode: { type: 'string' },\n      elements: {\n        type: 'array',\n        items: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            index: { type: 'integer' }, role: { type: 'string' },\n            label: { type: 'string' },\n            x: { oneOf: [{ type: 'integer' }, { type: 'null' }] },\n            y: { oneOf: [{ type: 'integer' }, { type: 'null' }] },\n          },\n        },\n      },\n      screenshotFile: { oneOf: [{ type: 'string' }, { type: 'null' }] },\n      ...IMAGE_FIELD,\n    }), render: renderWithImage },\n    execute: wrap('screen_observe', (args, cfg2, exec) => screenObserve(ctx, args, cfg2, exec)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'screen_zoom',\n    description:\n      '区域截图直读：裁剪窗口某块区域（截图像素坐标）为 ≤500px JPEG 并以图片返回，当前对话模型直接看图。' +\n      '用于\"放大某块区域细看\"（小字、图标、图表），图片 token 远小于整窗截图。' +\n      '坐标范围可用 screen_observe 的结果里的窗口截图尺寸（截图像素）估算；返回的图片即所见区域，' +\n      '之后 computer_click(x=,y=) 的坐标仍指整窗截图像素 —— 若需要点击 zoom 图内坐标，请先看参照。',\n    parameters: {\n      pid: { type: 'integer', description: '可选：目标窗口所属进程 pid（screen_observe 输出）；缺省按 window_id 解析。' },\n      window_id: { type: 'integer', required: true, description: '目标窗口 id（screen_observe 或 app_list 输出）。' },\n      x1: { type: 'integer', description: '可选：区域左边界（整窗截图像素），默认 0。' },\n      y1: { type: 'integer', description: '可选：区域上边界，默认 0。' },\n      x2: { type: 'integer', description: '可选：区域右边界，默认窗口截图宽。' },\n      y2: { type: 'integer', description: '可选：区域下边界，默认窗口截图高。' },\n    },\n    output: { ...OUT(IMAGE_FIELD), render: renderWithImage },\n    execute: wrap('screen_zoom', (args, cfg2, exec) => screenZoom(ctx, args, cfg2, exec)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_click',\n    description: '点击：传入 screen_observe 输出的元素编号（element），或窗口截图像素坐标（x,y）。点击的是 cua-driver 的虚拟光标，不抢真实鼠标。',\n    parameters: { ...TARGET_PARAMS, count: { type: 'integer', description: '可选：点击次数，默认 1。' } },\n    output: OUT(),\n    execute: wrap('computer_click', (args, cfg2) => click(args, cfg2)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_double_click',\n    description: '双击：element 编号 或 x/y 坐标。',\n    parameters: TARGET_PARAMS,\n    output: OUT(),\n    execute: wrap('computer_double_click', (args, cfg2) => doubleClick(args, cfg2)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_right_click',\n    description: '右键点击：element 编号 或 x/y 坐标。',\n    parameters: TARGET_PARAMS,\n    output: OUT(),\n    execute: wrap('computer_right_click', (args, cfg2) => rightClick(args, cfg2)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_type',\n    description: '文本输入：向当前焦点（或指定元素）输入一段文本。若驱动拒绝后台投递，前台重试会先请求本次用户批准并可能切换窗口焦点。不要在密码框使用——密码必须由用户本人输入（敏感输入保护）。',\n    parameters: {\n      text: { type: 'string', required: true, description: '要输入的文本。' },\n      element: TARGET_PARAMS.element,\n    },\n    output: OUT(),\n    execute: wrap('computer_type', (args, cfg2, exec) => typeText(args, cfg2, {\n      approval: ctx.approval,\n      agent: exec?.agent,\n      signal: exec?.signal,\n    })),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_key',\n    description: '按键 / 快捷键：如 return、tab、escape、cmd+c、shift+tab。若驱动拒绝后台投递，前台重试会先请求本次用户批准并可能切换窗口焦点。',\n    parameters: {\n      key: { type: 'string', required: true, description: '按键名或组合（示例: return / cmd+c / shift+tab / cmd+shift+p）。' },\n    },\n    output: OUT(),\n    execute: wrap('computer_key', (args, cfg2, exec) => key(args, cfg2, {\n      approval: ctx.approval,\n      agent: exec?.agent,\n      signal: exec?.signal,\n    })),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_scroll',\n    description: '滚动：在目标窗口内向上/下/左/右滚动。',\n    parameters: {\n      direction: { type: 'string', enum: ['up', 'down', 'left', 'right'], description: '滚动方向，默认 down。' },\n      amount: { type: 'integer', description: '可选：滚动格数，默认 3。' },\n      element: TARGET_PARAMS.element,\n    },\n    output: OUT(),\n    execute: wrap('computer_scroll', (args, cfg2) => scroll(args, cfg2)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_drag',\n    description: '拖拽：在快照窗口内从 (from_x,from_y) 拖到 (to_x,to_y)，坐标为窗口本地截图像素。',\n    parameters: {\n      from_x: { type: 'integer', required: true, description: '起点 x（截图像素）。' },\n      from_y: { type: 'integer', required: true, description: '起点 y。' },\n      to_x: { type: 'integer', required: true, description: '终点 x。' },\n      to_y: { type: 'integer', required: true, description: '终点 y。' },\n      duration_ms: { type: 'integer', description: '可选：拖拽耗时毫秒，默认 500。' },\n    },\n    output: OUT(),\n    execute: wrap('computer_drag', (args, cfg2) => drag(args, cfg2)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'computer_wait',\n    description: '等待：暂停一段时间（如等待界面加载/动画完成），不调用引擎。',\n    parameters: {\n      ms: { type: 'integer', required: true, description: '等待毫秒数（1-60000）。' },\n    },\n    output: OUT(),\n    execute: wrap('computer_wait', (args) => wait(args)),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'app_list',\n    description: '列出当前正在运行的应用（名称 + pid），用于选择要操作的目标。',\n    parameters: {},\n    output: OUT({ apps: {\n      type: 'array',\n      items: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          name: { type: 'string' }, pid: { type: 'integer' }, active: { type: 'boolean' },\n        },\n      },\n    } }),\n    execute: wrap('app_list', () => listApps()),\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'app_launch',\n    description: '启动一个应用（后台启动，不抢焦点；可选 bring_to_front 前置到前台）。用于\"打开应用\"这一步。',\n    parameters: {\n      name: {\n        type: 'string',\n        description: '应用显示名（如 \"备忘录\"）。与 bundle_id 二选一。',\n      },\n      bundle_id: {\n        type: 'string',\n        description: '应用 bundle id（如 com.apple.Notes）。优先于 name。',\n      },\n      bring_to_front: {\n        type: 'boolean',\n        description: '可选：启动后是否前置到前台（默认 false，后台启动）。',\n      },\n      creates_new_instance: {\n        type: 'boolean',\n        description: '可选：强制启动新实例（open -n），用于并发多会话隔离。',\n      },\n    },\n    output: OUT({ pid: { oneOf: [{ type: 'integer' }, { type: 'null' }] } }),\n    execute: wrap('app_launch', (args) => launchApp(args)),\n  }))\n\n  ctx.logger?.info('dsh-computer-use: 12 个工具已注册（screen_observe / screen_zoom / computer_click / double / right / type / key / scroll / drag / wait / app_list / app_launch）')\n}\n\nexport default { name, inject, Config, apply }\n"
    },
    {
      "path": "lib/guard.js",
      "content": "/**\n * guard.js —— 安全护栏（P3）。\n *\n * 1. 区域限制：仅允许操作 allowedApps 白名单中的应用（会话级）。\n * 2. 危险操作审批：目标标签命中危险词（删除/支付/购买/转账…）→ ctx.approval 征询用户。\n * 3. 敏感输入保护：密码框（AXSecureTextField）永不让模型输入——type 直接拒绝，click 需审批。\n * 4. 快照 TTL / 无快照拒绝：已在 snapshot.js 实现（动作一律要求新鲜快照）。\n */\nimport { getSnapshot } from './snapshot.js'\n\n/** 危险词表（命中即审批）。 */\nconst DANGEROUS_PATTERNS = [\n  /删除|移除|清空|清倒|格式化|卸载|永久/,\n  /支付|付款|购买|下单|结账|转账|汇款|提交订单|确认交易/,\n  /退出登录|注销|登出/,\n]\n\n/** 密码类 AX role（macOS）。 */\nconst PASSWORD_ROLES = new Set(['AXSecureTextField', 'AXPasswordField'])\n\n/** 区域限制只约束\"操作类\"工具；观察/列表/启动为只读或无害，不受限。 */\nconst OPERATION_TOOLS = new Set([\n  'computer_click', 'computer_double_click', 'computer_right_click',\n  'computer_type', 'computer_key', 'computer_scroll', 'computer_drag',\n])\n\n/** 目标标签是否命中危险词。 */\nexport function isDangerousLabel(label) {\n  const s = String(label || '')\n  return DANGEROUS_PATTERNS.some((re) => re.test(s))\n}\n\n/**\n * 统一动作前置守卫。\n * @param {object} ctx - Cordis 上下文（提供 approval 服务）\n * @param {object} cfg - 插件配置（allowedApps）\n * @param {string} toolName - 当前工具名\n * @param {object} args - 工具参数\n * @param {object} exec - 工具执行上下文（exec.agent）\n * @returns {Promise<{ok:boolean, reason?:string}>} 通过返回 {ok:true}\n */\nexport async function guard(ctx, cfg, toolName, args, exec) {\n  const snap = getSnapshot()\n\n  // 所有操作工具都必须先建立快照；白名单为空也不能绕过这一安全边界。\n  if (OPERATION_TOOLS.has(toolName) && !snap) {\n    return { ok: false, reason: '没有可用的观察快照：请先调用 screen_observe 再执行动作。' }\n  }\n\n  // 1. 区域限制：allowedApps 非空时，操作类工具的快照窗口应用必须在白名单内\n  if (OPERATION_TOOLS.has(toolName) && cfg.allowedApps && cfg.allowedApps.length > 0) {\n    if (!snap) {\n      return { ok: false, reason: '区域限制：先调用 screen_observe 建立快照才能操作。' }\n    }\n    if (!cfg.allowedApps.includes(snap.appName)) {\n      return {\n        ok: false,\n        reason: `区域限制：应用 \"${snap.appName}\" 不在允许操作列表（${cfg.allowedApps.join(' / ')}）中，已拒绝。`,\n      }\n    }\n  }\n\n  // 2/3. 元素级检测（仅 element 编号模式可预知目标；坐标模式无法预知，靠快照 TTL 兜底）\n  if (args.element !== undefined && args.element !== null && snap) {\n    const info = snap.entries?.get(Number(args.element))\n    const role = info?.role || ''\n    const label = info?.label || ''\n\n    // 敏感输入保护：密码框\n    if (PASSWORD_ROLES.has(role)) {\n      if (toolName === 'computer_type') {\n        return { ok: false, reason: '敏感输入保护：密码框拒绝自动输入——密码/密钥必须由用户本人输入。' }\n      }\n      // 点击密码框本身 → 询问\n      const outcome = await askApproval(ctx, exec, toolName, `检测到密码输入框\"${label || role}\"，确认执行 ${toolName}？`)\n      if (outcome !== 'allowed-once') {\n        return { ok: false, reason: `未获批准（${outcome}），已取消。` }\n      }\n      return { ok: true }\n    }\n\n    // 危险操作审批\n    if (isDangerousLabel(label)) {\n      const outcome = await askApproval(ctx, exec, toolName, `即将对\"${label}\"执行 ${toolName}——该目标可能触发删除/支付等危险操作，是否继续？`)\n      if (outcome !== 'allowed-once') {\n        return { ok: false, reason: `危险操作未获批准（${outcome}），已取消。` }\n      }\n    }\n  }\n\n  return { ok: true }\n}\n\n/** 通过 ctx.approval 征询用户（失败关闭：无 approval/agent 时视为不可用）。 */\nasync function askApproval(ctx, exec, toolName, reason) {\n  if (!ctx.approval || !exec?.agent) return 'unavailable'\n  try {\n    return await ctx.approval.request({ agent: exec.agent, toolName, reason })\n  } catch {\n    return 'unavailable'\n  }\n}\n"
    },
    {
      "path": "lib/snapshot.js",
      "content": "/**\n * snapshot.js —— 观察快照缓存。\n *\n * screen_observe 的结果有 TTL：过期后任何依赖编号/坐标的动作都会被拒绝，\n * 要求重新观察（对应项目书安全设计第 5 条\"过期状态拒绝\"）。\n * element_token 自带引擎侧 snapshot 校验，双重保险。\n * 快照同时记录 appName（区域限制）与元素 role/label（危险/敏感检测）。\n */\n\n/** 当前快照（单会话单窗口模型，P2 可扩展为多窗口表）。 */\nlet snapshot = null\n\n/**\n * 保存一次 screen_observe 的快照。\n * @param {object} s\n * @param {Map<number,{token:string,role?:string,label?:string}>} s.entries - 编号 → 元素信息\n */\nexport function setSnapshot(s) {\n  snapshot = s\n}\n\n/** 读取当前快照（可能为 null）。 */\nexport function getSnapshot() {\n  return snapshot\n}\n\n/** 快照是否新鲜（在 TTL 内）。 */\nexport function isFresh(ttlMs) {\n  return Boolean(snapshot) && Date.now() - snapshot.at <= ttlMs\n}\n\n/** 清除快照（例如发生明显环境变化后）。 */\nexport function clearSnapshot() {\n  snapshot = null\n}\n\n/**\n * 校验并取回编号对应的元素信息。\n * @param {number} index - screen_observe 输出的编号（= element_index）\n * @param {number} ttlMs - 快照 TTL\n * @returns {{pid:number, token:string, windowId:number, role?:string, label?:string}}\n * @throws 快照缺失 / 过期 / 编号不存在时抛出带指引的错误\n */\nexport function resolveToken(index, ttlMs) {\n  if (!snapshot) {\n    throw new Error('没有可用的观察快照：请先调用 screen_observe 再执行动作。')\n  }\n  if (!isFresh(ttlMs)) {\n    clearSnapshot()\n    throw new Error(`观察快照已过期（超过 ${Math.round(ttlMs / 1000)} 秒）：请重新调用 screen_observe。`)\n  }\n  const entry = snapshot.entries?.get(index)\n  if (!entry || !entry.token) {\n    throw new Error(`编号 [${index}] 不在当前快照中：请重新调用 screen_observe 获取最新编号。`)\n  }\n  return {\n    pid: snapshot.pid,\n    token: entry.token,\n    windowId: snapshot.windowId,\n    role: entry.role,\n    label: entry.label,\n  }\n}\n\n/**\n * 取回快照的窗口定位信息（坐标模式使用 window-local 像素）。\n */\nexport function resolveWindow(ttlMs) {\n  if (!snapshot) {\n    throw new Error('没有可用的观察快照：请先调用 screen_observe 再执行动作。')\n  }\n  if (!isFresh(ttlMs)) {\n    clearSnapshot()\n    throw new Error(`观察快照已过期（超过 ${Math.round(ttlMs / 1000)} 秒）：请重新调用 screen_observe。`)\n  }\n  return { pid: snapshot.pid, windowId: snapshot.windowId }\n}\n"
    },
    {
      "path": "lib/actions.js",
      "content": "/**\n * actions.js —— 动作工具实现：点击 / 双击 / 右键 / 输入 / 按键 / 滚动 / 拖拽。\n *\n * 每个动作都基于 screen_observe 的快照：\n *  - element 编号模式 → 透传 element_token（引擎校验快照是否过期）\n *  - x/y 坐标模式 → 使用快照窗口的 window-local 像素坐标\n */\nimport { cuaCall, normalizeMcp, withSession } from './cua.js'\nimport { getSnapshot } from './snapshot.js'\nimport { resolveToken, resolveWindow } from './snapshot.js'\nimport { humanClick, resolveClickTarget, screenPointOf, windowLocalOf } from './human.js'\n\n/**\n * 构造一次\"基于编号或坐标\"的引擎调用参数。\n * 坐标语义：screen_observe 输出的元素坐标是屏幕 pt（cua-driver 0.19.3 的\n * frame 即屏幕坐标），引擎 click/scroll/drag 需要 window-local，故换算。\n * @returns {object} 传给 cua-driver 的参数字段\n */\nfunction targetArgs(args, cfg, extra = {}) {\n  const out = {}\n  const snap = getSnapshot()\n  if (args.element !== undefined && args.element !== null) {\n    const { pid, token } = resolveToken(Number(args.element), cfg.ttlMs)\n    out.pid = pid\n    out.element_token = token\n  } else if (args.x !== undefined || args.y !== undefined) {\n    if (args.x === undefined || args.y === undefined) {\n      throw new Error('坐标模式必须同时提供 x 和 y。')\n    }\n    const { pid, windowId } = resolveWindow(cfg.ttlMs)\n    const local = windowLocalOf(Number(args.x), Number(args.y), snap)\n    out.pid = pid\n    out.window_id = windowId // 坐标点击需 window_id 定位目标窗口（避免多窗口歧义）\n    out.x = local.x\n    out.y = local.y\n  } else {\n    throw new Error('必须提供 element（观察编号）或 x/y 坐标。')\n  }\n  return withSession({ ...out, ...extra })\n}\n\n/** 通用动作执行：调用引擎并返回统一结果。 */\nasync function runAction(label, tool, args, cfg, extra = {}) {\n  const payload = targetArgs(args, cfg, extra)\n  const value = normalizeMcp(await cuaCall(tool, payload))\n  const refusal = engineRefusal(value)\n  if (refusal) return { ok: false, result: `${label} 被引擎拒绝：${refusal}` }\n  const detail = typeof value === 'string' ? value : JSON.stringify(value)\n  return { ok: true, result: `${label} 完成：${detail}` }\n}\n\nfunction engineRefusal(value) {\n  if (value && typeof value === 'object' && !Array.isArray(value)) {\n    const effect = value.effect\n    if (effect === 'refused' || effect === 'rejected' || effect === 'suspected_noop') {\n      const code = value.code ? ` (${value.code})` : ''\n      const reason = value.escalation?.reason || value.reason || value.message || ''\n      return `${effect}${code}${reason ? ' ' + reason : ''}`\n    }\n    if (value.code === 'background_unavailable') {\n      const reason = value.escalation?.reason || value.reason || value.message || ''\n      return `background_unavailable${reason ? ' ' + reason : ''}`\n    }\n    if (typeof value.error === 'string') return value.error.slice(0, 200)\n  }\n  return null\n}\n\n/** Retry only driver-declared background delivery failures in the foreground. */\nfunction requiresForegroundRetry(value) {\n  return Boolean(value && typeof value === 'object' && !Array.isArray(value)\n    && (value.code === 'background_unavailable'\n      || value.escalation === 'foreground'\n      || value.escalation?.recommended === 'foreground'))\n}\n\nasync function callWithForegroundFallback(call, tool, payload, { approval, agent, toolName, signal, platform = process.platform } = {}) {\n  let value = normalizeMcp(await call(tool, payload))\n  const supportsDeliveryMode = tool === 'type_text' || platform === 'win32'\n  if (!supportsDeliveryMode || !requiresForegroundRetry(value)) return value\n\n  const snap = getSnapshot()\n  const app = snap?.appName ? `（目标应用：${snap.appName}）` : ''\n  if (!approval || !agent) {\n    return {\n      effect: 'refused',\n      code: 'foreground_approval_required',\n      reason: `后台投递不可用；前台重试可能改变焦点${app}，当前没有可用的用户审批服务。`,\n    }\n  }\n\n  let outcome = 'unavailable'\n  try {\n    outcome = await approval.request({\n      agent,\n      toolName,\n      reason: `驱动未能确认后台投递可用或建议使用前台模式。前台重试可能把目标窗口置于前台并向其输入/发送按键${app}；是否仅为本次操作批准？`,\n      signal,\n    })\n  } catch { /* 失败关闭：没有明确批准就不切到前台 */ }\n  if (outcome !== 'allowed-once' || signal?.aborted) {\n    return {\n      effect: 'refused',\n      code: outcome === 'unavailable' ? 'foreground_approval_required' : 'foreground_approval_denied',\n      reason: `前台重试未获本次批准（${outcome}），已停止。`,\n    }\n  }\n\n  return normalizeMcp(await call(tool, { ...payload, delivery_mode: 'foreground' }))\n}\n\n/**\n * 真人点击：解析目标（编号或坐标）→ 光标滑行 → 像素级点击。\n * @returns {Promise<{ok:boolean, result:string}>}\n */\nasync function humanAction(label, args, cfg, extra = {}) {\n  let target\n  const snap = getSnapshot()\n  if (args.element !== undefined && args.element !== null) {\n    target = resolveClickTarget(Number(args.element), cfg.ttlMs)\n  } else if (args.x !== undefined && args.y !== undefined) {\n    const { pid, windowId } = resolveWindow(cfg.ttlMs)\n    const sx = Number(args.x)\n    const sy = Number(args.y)\n    const local = windowLocalOf(sx, sy, snap)\n    target = {\n      pid,\n      windowId,\n      x: local.x,\n      y: local.y,\n      sx,\n      sy,\n    }\n  } else {\n    throw new Error('必须提供 element（观察编号）或 x/y 坐标。')\n  }\n  const value = await humanClick({ ...target, ...extra })\n  const refusal = engineRefusal(value)\n  if (refusal) return { ok: false, result: `${label} 被引擎拒绝：${refusal}` }\n  const detail = typeof value === 'string' ? value : JSON.stringify(value)\n  return { ok: true, result: `${label} 完成（虚拟光标滑行+点击）：${detail}` }\n}\n\n/** computer_click —— 真人操作：光标滑行 + 像素点击 */\nexport async function click(args, cfg) {\n  const extra = {}\n  if (args.count) extra.count = Number(args.count)\n  return humanAction('点击', args, cfg, extra)\n}\n\n/** computer_double_click */\nexport async function doubleClick(args, cfg) {\n  return humanAction('双击', args, cfg, { count: 2 })\n}\n\n/** computer_right_click */\nexport async function rightClick(args, cfg) {\n  return humanAction('右键点击', args, cfg, { button: 'right' })\n}\n\n/** computer_type —— 文本输入（可指定元素，否则输入到前台应用当前焦点） */\nexport async function typeText(args, cfg, { call = cuaCall, resolve = resolveWindow, approval, agent, signal, platform = process.platform } = {}) {\n  if (!args.text) throw new Error('computer_type: 缺少 text 参数。')\n  const payload = withSession({ text: String(args.text), delivery_mode: 'background' })\n  if (args.element !== undefined && args.element !== null) {\n    const { pid, token } = resolveToken(Number(args.element), cfg.ttlMs)\n    payload.pid = pid\n    payload.element_token = token\n  } else {\n    // 即使输入当前焦点，也必须绑定到新鲜观察快照的窗口，禁止盲发到 desktop scope。\n    const { pid, windowId } = resolve(cfg.ttlMs)\n    payload.pid = pid\n    payload.window_id = windowId\n  }\n  const value = await callWithForegroundFallback(call, 'type_text', payload, {\n    approval, agent, toolName: 'computer_type', signal, platform,\n  })\n  const refusal = engineRefusal(value)\n  if (refusal) return { ok: false, result: `输入被引擎拒绝：${refusal}` }\n  const detail = typeof value === 'string' ? value : JSON.stringify(value)\n  return { ok: true, result: `输入完成：${detail}` }\n}\n\n/** computer_key —— 按键 / 快捷键（如 return、cmd+c） */\nexport async function key(args, cfg, options = {}) {\n  return dispatchKey(args, cfg, options)\n}\n\n/**\n * computer_key dispatch with optional dependencies for deterministic tests.\n * Bare keys stay on press_key for classic Win32; modifier combinations use\n * hotkey so UIA/XAML accelerators receive the event.\n */\nexport async function dispatchKey(args, cfg, { call = cuaCall, resolve = resolveWindow, approval, agent, signal, platform = process.platform } = {}) {\n  if (!args.key) throw new Error('computer_key: 缺少 key 参数。')\n  const parts = String(args.key).toLowerCase().split('+').map((s) => s.trim())\n  const MODS = new Set(['cmd', 'command', 'ctrl', 'control', 'option', 'alt', 'shift', 'fn'])\n  const modifiers = parts.filter((p) => MODS.has(p)).map((p) => {\n    if (p === 'command') return 'cmd'\n    if (p === 'control') return 'ctrl'\n    if (p === 'option') return 'alt'\n    return p\n  })\n  const keyName = parts.filter((p) => !MODS.has(p))[0]\n  if (!keyName) throw new Error('computer_key: 无法解析按键（示例: return / cmd+c / shift+tab）。')\n  const isCombo = modifiers.length > 0\n  // Both routes require a fresh snapshot and retain pid + window_id targeting.\n  // 注：只传 pid 在多窗口应用（QQ 等）会歧义，必须带 window_id\n  const { pid, windowId } = resolve(cfg.ttlMs)\n  const target = { pid, window_id: windowId }\n  const deliveryMode = platform === 'win32' ? { delivery_mode: 'background' } : {}\n  const payload = withSession(isCombo\n    ? { keys: [...modifiers, keyName], ...target, ...deliveryMode }\n    : { key: keyName, ...target, ...deliveryMode })\n  const tool = isCombo ? 'hotkey' : 'press_key'\n  const value = await callWithForegroundFallback(call, tool, payload, {\n    approval, agent, toolName: 'computer_key', signal, platform,\n  })\n  const refusal = engineRefusal(value)\n  if (refusal) return { ok: false, result: `按键被引擎拒绝：${refusal}` }\n  const detail = typeof value === 'string' ? value : JSON.stringify(value)\n  return { ok: true, result: `按键完成 (${String(args.key)})：${detail}` }\n}\n\n/** computer_scroll */\nexport async function scroll(args, cfg, { call = cuaCall, resolve = resolveWindow } = {}) {\n  const dir = args.direction || 'down'\n  if (!['up', 'down', 'left', 'right'].includes(dir)) {\n    throw new Error('computer_scroll: direction 必须是 up/down/left/right。')\n  }\n  const payload = withSession({ direction: dir })\n  if (args.amount) payload.amount = Number(args.amount)\n  if (args.element !== undefined && args.element !== null) {\n    const { pid, token } = resolveToken(Number(args.element), cfg.ttlMs)\n    payload.pid = pid\n    payload.element_token = token\n  } else {\n    const { pid, windowId } = resolve(cfg.ttlMs)\n    payload.pid = pid\n    payload.window_id = windowId\n  }\n  const value = normalizeMcp(await call('scroll', payload))\n  const refusal = engineRefusal(value)\n  if (refusal) return { ok: false, result: `滚动被引擎拒绝：${refusal}` }\n  const detail = typeof value === 'string' ? value : JSON.stringify(value)\n  return { ok: true, result: `滚动完成 (${dir})：${detail}` }\n}\n\n/** computer_drag —— 拖拽（坐标 = 窗口本地截图像素，与观察输出同空间） */\nexport async function drag(args, cfg, { call = cuaCall, resolve = resolveWindow } = {}) {\n  const { pid, windowId } = resolve(cfg.ttlMs)\n  if ([args.from_x, args.from_y, args.to_x, args.to_y].some((v) => v === undefined)) {\n    throw new Error('computer_drag: 需要 from_x/from_y/to_x/to_y。')\n  }\n  const payload = withSession({\n    pid,\n    window_id: windowId,\n    from_x: Number(args.from_x),\n    from_y: Number(args.from_y),\n    to_x: Number(args.to_x),\n    to_y: Number(args.to_y),\n  })\n  if (args.duration_ms) payload.duration_ms = Number(args.duration_ms)\n  const value = normalizeMcp(await call('drag', payload))\n  const refusal = engineRefusal(value)\n  if (refusal) return { ok: false, result: `拖拽被引擎拒绝：${refusal}` }\n  const detail = typeof value === 'string' ? value : JSON.stringify(value)\n  return { ok: true, result: `拖拽完成：${detail}` }\n}\n\n/** computer_wait —— 本地等待（不调引擎） */\nexport async function wait(args) {\n  const ms = Math.max(0, Math.min(Number(args.ms) || 1000, 60000))\n  await new Promise((r) => setTimeout(r, ms))\n  return { ok: true, result: `已等待 ${ms}ms。` }\n}\n\n/** app_list —— 列出应用 */\nexport async function listApps() {\n  const value = await cuaCall('list_apps')\n  const apps = (value.apps || []).filter((a) => a.running)\n  const lines = apps.map((a) => {\n    const win = a.windows && a.windows.length > 0 ? ` (${a.windows.length} 窗口)` : ''\n    return `- ${a.name}${win} [pid=${a.pid}]${a.active ? ' ★活动' : ''}`\n  })\n  const result = `正在运行的应用（${apps.length} 个）：\\n${lines.join('\\n')}`\n  return { ok: true, result, apps: apps.map((a) => ({ name: a.name, pid: a.pid, active: a.active })) }\n}\n\n/** app_launch —— 启动应用（后台），可选前置 */\nexport async function launchApp(args) {\n  if (!args.name && !args.bundle_id) {\n    throw new Error('app_launch: 需要 name（应用名）或 bundle_id。')\n  }\n  const payload = {}\n  if (args.bundle_id) payload.bundle_id = String(args.bundle_id)\n  else payload.name = String(args.name)\n  if (args.creates_new_instance) payload.creates_new_instance = true\n  const launched = await cuaCall('launch_app', payload)\n\n  // 若请求前置，找 pid 并 bring_to_front\n  let pid = launched?.pid ?? null\n  let frontNote = ''\n  if (args.bring_to_front && pid) {\n    await cuaCall('bring_to_front', { pid })\n    frontNote = ' 已前置'\n  }\n\n  const detail = typeof launched === 'string' ? launched : JSON.stringify(launched)\n  return {\n    ok: true,\n    result: `应用已启动${frontNote}：${detail}`,\n    pid,\n  }\n}\n"
    },
    {
      "path": "lib/cua.js",
      "content": "/**\n * cua.js —— cua-driver 引擎调用封装。\n *\n * 通过 `cua-driver call <tool> '<json-args>'` 的子进程方式调用引擎。\n * 零外部依赖：不需要 MCP SDK，CLI 即接口。\n *\n * 引擎二进制定位见 resolveBin()：CUA_DRIVER_BIN → PATH → 官方安装器路径 → 常见安装路径。\n */\nimport { spawn } from 'node:child_process'\nimport { existsSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { join, win32 } from 'node:path'\n\n/**\n * 解析引擎二进制路径（优先级）：\n *   1. 环境变量 CUA_DRIVER_BIN（显式指定）\n *   2. PATH 目录扫描（cua-driver / cua-driver.exe）\n *   3. 官方安装器路径：~/.cua-driver/packages/current/<exe>\n *   4. 常见安装路径：~/.local/bin（旧版安装器默认位置）、\n *      /usr/local/bin、/opt/homebrew/bin（Apple Silicon）、Windows %LOCALAPPDATA%\n *   4. 兜底 'cua-driver'（交给 spawn 报 ENOENT，错误信息含自救指引）\n *\n * 说明：GUI 应用（harness-desktop）的 PATH 通常不含 shell 的 ~/.local/bin，\n * 因此必须探测官方安装器的默认位置，否则 macOS 用户开箱即 ENOENT。\n */\nexport function resolveBin({ platform = process.platform, env = process.env, home = homedir(), exists = existsSync } = {}) {\n  const explicit = env.CUA_DRIVER_BIN\n  if (explicit) return explicit\n  const sep = platform === 'win32' ? ';' : ':'\n  const exe = platform === 'win32' ? 'cua-driver.exe' : 'cua-driver'\n  const pathJoin = platform === 'win32' ? win32.join : join\n  for (const dir of (env.PATH || '').split(sep)) {\n    if (!dir) continue\n    try { if (exists(pathJoin(dir, exe))) return pathJoin(dir, exe) } catch { /* 忽略 */ }\n  }\n  const common = [\n    pathJoin(home, '.cua-driver', 'packages', 'current', exe),\n    pathJoin(home, '.local', 'bin', exe),\n    pathJoin('/usr/local/bin', exe),\n    pathJoin('/opt/homebrew/bin', exe),\n    pathJoin(home, 'AppData', 'Local', 'cua-driver', exe),\n  ]\n  for (const p of common) {\n    try { if (exists(p)) return p } catch { /* 忽略 */ }\n  }\n  return 'cua-driver'\n}\n\nexport const CUA_BIN = resolveBin()\n\n/**\n * 插件统一的虚拟光标会话 id：所有动作绑定同一会话，\n * 光标主题/运动参数才能稳定生效（会话级）。\n */\nexport const CUA_SESSION = process.env.CUA_SESSION || 'dsh-computer-use'\n\n/** 给动作类调用注入统一会话（观察类只读工具不需要）。 */\nexport function withSession(args = {}) {\n  return { session: CUA_SESSION, ...args }\n}\n\nexport function isSessionEndedError(message) {\n  return /\\bsession\\s+(?:'[^']+'\\s+)?has\\s+ended\\b|\\brevive\\s+it\\b/i.test(String(message || ''))\n}\n\n/** Create the retry wrapper with an injectable raw call for deterministic tests. */\nexport function createCuaCall(callRaw, session = CUA_SESSION) {\n  if (typeof callRaw !== 'function') throw new TypeError('createCuaCall requires a raw-call function')\n  return async function callWithSessionRecovery(tool, args = {}) {\n    try {\n      return await callRaw(tool, args)\n    } catch (err) {\n      if (tool !== 'start_session' && isSessionEndedError(err?.message)) {\n        await callRaw('start_session', { session }).catch(() => undefined)\n        return callRaw(tool, args)\n      }\n      throw err\n    }\n  }\n}\n\n/** Call a cua-driver tool with session recovery enabled. */\nexport const cuaCall = createCuaCall(rawCall)\n\n/** 底层单次调用（不含会话自愈）。 */\nfunction rawCall(tool, args = {}) {\n  return new Promise((resolve, reject) => {\n    const child = spawn(CUA_BIN, ['call', tool, JSON.stringify(args)], {\n      stdio: ['ignore', 'pipe', 'pipe'],\n    })\n    let out = ''\n    let err = ''\n    child.stdout.on('data', (d) => { out += d })\n    child.stderr.on('data', (d) => { err += d })\n    child.on('error', (e) => {\n      const hint = e.code === 'ENOENT'\n        ? `未找到 cua-driver：请确保它已安装并在 PATH 中，或确认官方安装器路径 ~/.cua-driver/packages/current/cua-driver.exe 可用，或设置环境变量 CUA_DRIVER_BIN 指向完整路径。`\n        : ''\n      reject(new Error(`cua-driver 无法启动 (${CUA_BIN}): ${e.message}${hint ? ' ' + hint : ''}`))\n    })\n    child.on('close', (code) => {\n      if (code !== 0) {\n        const msg = (err || out).trim()\n        reject(new Error(`cua-driver ${tool} 失败 (exit ${code}): ${msg.slice(0, 800)}`))\n        return\n      }\n      try {\n        resolve(JSON.parse(out))\n      } catch {\n        reject(new Error(`cua-driver ${tool} 返回非 JSON: ${out.slice(0, 500)}`))\n      }\n    })\n  })\n}\n\n/**\n * 归一化 MCP 形状的返回：若结果带 content 数组（[{type:'text',text}]），\n * 提取文本拼接；否则原样返回。\n */\nexport function normalizeMcp(value) {\n  if (value && Array.isArray(value.content)) {\n    const texts = value.content\n      .filter((b) => b && b.type === 'text' && typeof b.text === 'string')\n      .map((b) => b.text)\n    if (texts.length > 0) return texts.join('\\n')\n  }\n  return value\n}\n"
    },
    {
      "path": "lib/human.js",
      "content": "/**\n * human.js —— 真人操作模块：像素级虚拟光标（看得见过程）。\n *\n * 坐标语义（cua-driver 0.21+）：click / drag / scroll 的 x,y 均为\n * \"窗口本地截图像素\"（get_window_state 返回的 PNG 同一空间，左上原点）。\n * 因此坐标不再做任何 ×2 / 窗口偏移换算 —— 模型看到的截图坐标即动作坐标。\n *\n * 点击寻址：\n *   - element 编号模式 → 用引擎官方推荐的 element_token（AX 路径，精确定位，\n *     支持后台/隐藏窗口，无需坐标；引擎文档明确 \"Prefer element_token\"）\n *   - x/y 坐标模式 → 像素路径（CGEvent），坐标 = 窗口本地截图像素\n */\nimport { cuaCall, CUA_SESSION, withSession } from './cua.js'\nimport { getSnapshot } from './snapshot.js'\n\n/** 滑行段数（越多越平滑，真人手部轨迹感）。 */\nconst GLIDE_SEGMENTS = 5\n/** 每段间隔 ms。 */\nconst GLIDE_STEP_MS = 70\n/** 弧线高度（px，模拟人手弧线轨迹）。 */\nconst ARC_HEIGHT = 40\n\n/**\n * 光标滑行：从当前位置平滑移动到目标（分段 + 弧线）。最佳努力：\n * 滑行失败不阻断点击（0.21.0 的 move_cursor 目标形状与旧版不同，逐级尝试）。\n * @param {number} tx - 目标 x（窗口本地截图像素）\n * @param {number} ty - 目标 y\n * @param {object} opts - { pid, windowId } 用于窗口目标\n */\nexport async function glideCursor(tx, ty, opts = {}) {\n  const tryMove = (payload) => cuaCall('move_cursor', payload).catch(() => undefined)\n  // 当前光标位置（拿不到就从目标点直线过去）\n  let cur = null\n  try {\n    cur = await cuaCall('get_cursor_position', { session: CUA_SESSION })\n  } catch { /* 无光标信息 → 直线 */ }\n  const sx = cur?.x != null ? cur.x : tx\n  const sy = cur?.y != null ? cur.y : ty\n\n  for (let i = 1; i <= GLIDE_SEGMENTS; i++) {\n    const t = i / GLIDE_SEGMENTS\n    const x = sx + (tx - sx) * t\n    // 弧线：中间点抬高（模拟人手画弧）\n    const y = sy + (ty - sy) * t - Math.sin(t * Math.PI) * ARC_HEIGHT\n    await tryMove(withSession({ x, y, ...opts }))\n    await new Promise((r) => setTimeout(r, GLIDE_STEP_MS))\n  }\n  await tryMove(withSession({ x: tx, y: ty, ...opts }))\n}\n\n/**\n * 窗口本地截图像素 ⇄ 屏幕坐标换算不再需要：0.21.0 直接接受截图像素。\n * 保留函数仅为兼容旧调用（坐标原样返回）。\n */\nexport function windowLocalOf(x, y, _snap) {\n  return { x, y }\n}\n\n/**\n * 真人点击：滑行到目标 + 点击。\n * element 模式（带 token）走引擎 AX 路径（element_token，精确定位）；\n * 坐标模式走像素路径（x/y = 窗口本地截图像素，模型直接可见的坐标）。\n * @param {object} opts - { pid, windowId, x, y, sx, sy, token, count, button }\n */\nexport async function humanClick(opts) {\n  const { pid, windowId, x, y, sx, sy, token, count = 1, button = 'left' } = opts\n\n  // 1. 光标滑行到目标（最佳努力，看得见过程）\n  if (sx != null && sy != null) {\n    await glideCursor(sx, sy, { target: { kind: 'window', pid, window_id: windowId } })\n  }\n\n  // 2. 点击：token 优先（AX 路径），否则像素路径（窗口本地截图像素）\n  const payload = { session: CUA_SESSION, pid }\n  if (token) {\n    payload.element_token = token\n    // token 路径同样透传计数/按钮，否则双击/右键会静默退化成单次左键\n    payload.count = count\n    payload.button = button\n  } else {\n    if (x == null || y == null) throw new Error('humanClick: 缺少点击坐标（x/y）。')\n    payload.window_id = windowId\n    payload.x = x\n    payload.y = y\n    payload.count = count\n    payload.button = button\n  }\n  const value = await cuaCall('click', payload)\n  return value\n}\n\n/** 快照辅助：解析编号 → token + 坐标（截图像素空间）。 */\nexport function resolveClickTarget(index, ttlMs) {\n  const snap = getSnapshot()\n  if (!snap) throw new Error('没有可用的观察快照：请先调用 screen_observe。')\n  const entry = snap.entries?.get(index)\n  if (!entry) throw new Error(`编号 [${index}] 不在当前快照中。`)\n  const pt = screenPointOf(entry, snap)\n  const local = windowLocalOf(entry.x, entry.y, snap)\n  return {\n    pid: snap.pid,\n    windowId: snap.windowId,\n    token: entry.token || null,\n    x: local.x,\n    y: local.y,\n    sx: pt?.sx,\n    sy: pt?.sy,\n  }\n}\n\n/** 快照辅助：元素坐标（截图像素空间）。 */\nexport function screenPointOf(entry, _snap) {\n  if (!entry || entry.x == null || entry.y == null) return null\n  return { sx: entry.x, sy: entry.y }\n}"
    },
    {
      "path": "lib/observe.js",
      "content": "/**\n * observe.js —— screen_observe 工具实现（含原生视觉 Mode C / 观察者 Mode D）。\n *\n * 流程：list_windows 取窗口 → 选目标 → get_window_state 取 AX 树\n * → 精简为\"编号 + 角色 + 标签 + 中心坐标\"行 → 缓存快照。\n *\n * 坐标语义（cua-driver 0.21+ 实测）：所有动作坐标 = \"窗口本地截图像素\"，\n * 与 get_window_state 返回的截图 PNG 同一空间（左上原点）。因此：\n *   - 元素编号模式 → element_token（AX 路径，无需坐标）\n *   - x/y 坐标模式 → 直接透传截图像素，不做 ×2 / 窗口偏移换算\n *\n * 三种观察模式：\n *   - ax（默认）：只取 AX 树，零视觉 token 成本。\n *   - vision：DeepSeek 视觉观察者（ctx.llm → deepseek-v4-flash-vision-exp，\n *     可配置 visionProvider/visionModel）结构化描述截图；模型不可用时回退 GLM。\n *   - native：截图经 attachments 持久化后以图片块(\"原生直读\")返回 ——\n *     主对话模型（需支持 image 输入）直接看图，零外部 API。\n *   自动降级：AX 树为空（游戏/Canvas/Electron 不可解析）时，\n *   优先 native（route 支持 image）→ vision（有观察模型/GLM key）→ ax。\n */\nimport { withSession } from './cua.js'\nimport { cuaCall } from './cua.js'\nimport { setSnapshot } from './snapshot.js'\nimport {\n  deepseekVisionDescribe,\n  glmVisionDescribe,\n  glmVisionConfigured,\n  routeImageCapable,\n} from './vision.js'\n\n/** AX role 中值得展示的精简角色名（太长会刷爆上下文）。 */\nconst ROLE_SHORT = {\n  AXWindow: '窗口',\n  AXButton: '按钮',\n  AXTextField: '输入框',\n  AXTextArea: '文本框',\n  AXCheckBox: '复选框',\n  AXRadioButton: '单选',\n  AXComboBox: '下拉框',\n  AXMenuButton: '菜单按钮',\n  AXMenuItem: '菜单项',\n  AXLink: '链接',\n  AXTab: '标签页',\n  AXSlider: '滑块',\n  AXScrollBar: '滚动条',\n  AXTable: '表格',\n  AXCell: '单元格',\n  AXRow: '行',\n  AXOutline: '大纲',\n  AXList: '列表',\n  AXStaticText: '文本',\n  AXImage: '图片',\n  AXPopUpButton: '弹出按钮',\n  AXGroup: '分组',\n  AXToolbar: '工具栏',\n  AXSheet: '面板',\n  AXDialog: '对话框',\n}\n\nfunction shortRole(role) {\n  return ROLE_SHORT[role] || (role ? role.replace(/^AX/, '') : '元素')\n}\n\n/** 清洗为安全字符串：保证可无损 JSON 序列化（去孤立代理项）+ 截断。 */\nfunction safeStr(v, max = 120) {\n  let s = String(v ?? '')\n  // 孤立代理项（Safari/网页 AX 值常见）会导致 JSON 序列化失败\n  s = s.replace(/[\\uD800-\\uDFFF]/g, '\\uFFFD')\n  return s.slice(0, max)\n}\n\n/** 是否值得给编号（可交互或有关键文本）。 */\nfunction isActionable(e) {\n  const r = e.role || ''\n  if (['AXButton', 'AXTextField', 'AXTextArea', 'AXCheckBox', 'AXRadioButton',\n    'AXComboBox', 'AXMenuButton', 'AXMenuItem', 'AXLink', 'AXTab', 'AXSlider',\n    'AXPopUpButton', 'AXCell', 'AXRow', 'AXScrollBar'].includes(r)) return true\n  if (e.label || e.value) return true\n  return false\n}\n\n/** 元素中心坐标（截图像素空间，frame 与截图同空间）。非法/缺失时返回 null。 */\nfunction centerOf(e) {\n  const f = e.frame\n  if (!f) return null\n  const x = f.x + f.w / 2\n  const y = f.y + f.h / 2\n  if (!Number.isFinite(x) || !Number.isFinite(y)) return null\n  return { x: Math.round(x), y: Math.round(y) }\n}\n\n/** 渲染一行编号元素。 */\nfunction renderLine(e) {\n  const role = shortRole(e.role)\n  const label = safeStr(e.label || e.value || '')\n  const parts = [`[${e.element_index}] ${role}`]\n  if (label) parts.push(`\"${label}\"`)\n  const c = centerOf(e)\n  if (c) parts.push(`@(${c.x},${c.y})`)\n  return parts.join(' ')\n}\n\n/** 构造视觉提问（坐标系 = 截图像素 = 动作坐标）。 */\nfunction visionQuestion(w, h) {\n  return `这是一张电脑应用窗口的截图，宽 ${w}px，高 ${h}px（坐标原点左上角，坐标为窗口本地截图像素）。\n请用中文描述界面内容，并列出所有可交互元素（按钮、输入框、菜单、链接、图标等），每项格式：\n[序号] 类型 \"文字\" @(x,y)\n坐标 x,y 为该元素中心在截图中的像素位置。只输出列表，最多 30 项，不要多余解释。`\n}\n\n/** base64 → Buffer。 */\nfunction buf(b64) {\n  return Buffer.from(String(b64 || ''), 'base64')\n}\n\n/**\n * 把 get_window_state 的截图提交到 attachments（原生直读 / 观察者都需要）。\n * PNG 超过单图字节限额时自动降级为引擎 zoom（整窗 JPEG，≤500px 宽）。\n * @returns {Promise<{ref:object, width:number, height:number, compact:boolean}>}\n */\nasync function commitScreenshot(ctx, target, state, cfg) {\n  const attachments = ctx?.get?.('attachments')\n  if (!attachments) {\n    throw new Error('当前环境未挂载 attachments 服务，无法持久化截图（原生视觉不可用）。')\n  }\n  const pngBuf = buf(state.screenshot_png_b64)\n  const maxBytes = attachments.imageLimits?.maxImageBytes ?? 5 * 1024 * 1024\n  const compact = cfg.nativeImage === 'compact'\n    || (cfg.nativeImage !== 'full' && pngBuf.byteLength > maxBytes)\n\n  let data = pngBuf\n  let mediaType = state.screenshot_mime_type === 'image/jpeg' ? 'image/jpeg' : 'image/png'\n  let width = state.screenshot_width\n  let height = state.screenshot_height\n  let name = `screen-${target.pid}.png`\n\n  if (compact) {\n    // 整窗 zoom：x/y 用原始截图像素范围，引擎输出 ≤500px 宽的 JPEG\n    const w = state.screenshot_width || 1\n    const h = state.screenshot_height || 1\n    const zv = await cuaCall('zoom', withSession({\n      pid: target.pid,\n      window_id: target.window_id,\n      x1: 0,\n      y1: 0,\n      x2: w,\n      y2: h,\n    }))\n    const jpeg = buf(zv?.screenshot_png_b64)\n    if (jpeg.byteLength === 0) throw new Error('zoom 降级截图失败：引擎返回空图片。')\n    data = jpeg\n    mediaType = (zv?.mime_type === 'image/jpeg') ? 'image/jpeg' : 'image/jpeg'\n    width = zv?.width || width\n    height = zv?.height || height\n    name = `screen-${target.pid}-compact.jpg`\n  }\n\n  const ref = await attachments.saveImage({ data, mediaType, name })\n  return { ref, width, height, compact }\n}\n\n/** 观察者（Mode D）：DeepSeek 视觉模型描述，失败回退 GLM。 */\nasync function describeVision(ctx, cfg, state, target, exec, question) {\n  const w = state.screenshot_width || 0\n  const h = state.screenshot_height || 0\n  const q = question || visionQuestion(w, h)\n  // 1. 优先 DeepSeek 观察者（需 attachments 持久化 + llm 服务）\n  const attachments = ctx?.get?.('attachments')\n  const llm = ctx?.get?.('llm')\n  if (llm && attachments) {\n    try {\n      const { ref, compact } = await commitScreenshot(ctx, target, state, cfg)\n      const text = await deepseekVisionDescribe(ctx, cfg, {\n        imageRef: ref,\n        question: q,\n      })\n      return `（观察者 ${cfg.visionProvider}/${cfg.visionModel}${compact ? ' · 紧凑图' : ''}）\\n${text}`\n    } catch (err) {\n      // 观察者不可用 → 记录后走 GLM\n      return `（DeepSeek 观察者不可用：${err.message}）\\n${await glmVisionDescribe({\n        imageBase64: state.screenshot_png_b64,\n        mimeType: state.screenshot_mime_type === 'image/jpeg' ? 'image/jpeg' : 'image/png',\n        question: q,\n      }).catch((e2) => `（视觉理解失败：${e2.message}）`)}`\n    }\n  }\n  // 2. 无 llm/attachments：GLM 直传\n  return glmVisionDescribe({\n    imageBase64: state.screenshot_png_b64,\n    mimeType: state.screenshot_mime_type === 'image/jpeg' ? 'image/jpeg' : 'image/png',\n    question: q,\n  }).catch((err) => `（视觉理解失败：${err.message}）`)\n}\n\n/**\n * 执行 screen_observe。\n * @param {object} ctx - Cordis 上下文（llm / attachments 服务）\n * @param {object} args - { window?, mode?, query?, maxElements? }\n * @param {object} cfg - 插件配置（ttlMs / maxElements / nativeImage / visionProvider / visionModel）\n * @param {object} exec - 工具执行上下文（取当前 route）\n */\nexport async function screenObserve(ctx, args, cfg, exec) {\n  const wantMode = args.mode\n  const maxElements = args.maxElements || cfg.maxElements || 500\n\n  // 1. 窗口列表\n  const winList = await cuaCall('list_windows', { on_screen_only: true })\n  const windows = (winList.windows || []).filter((w) => w.window_id && (w.title || w.app_name))\n\n  if (windows.length === 0) {\n    return { ok: false, result: '当前没有可见窗口。' }\n  }\n\n  // 2. 选目标窗口：参数 window（pid / 标题子串）→ 否则 z 序最前\n  let target = null\n  const want = args.window\n  if (want !== undefined && want !== null && want !== '') {\n    const wantStr = String(want)\n    target = windows.find((w) => String(w.pid) === wantStr)\n      || windows.find((w) => (w.title || '').toLowerCase().includes(wantStr.toLowerCase()))\n      || windows.find((w) => (w.app_name || '').toLowerCase().includes(wantStr.toLowerCase()))\n  }\n  if (!target && want !== undefined && want !== null && want !== '') {\n    const candidates = windows\n      .map((w) => `${w.app_name || ''} · ${w.title || ''} · pid=${w.pid}`)\n      .join('\\n')\n    return {\n      ok: false,\n      result:\n        `未找到指定窗口「${String(want)}」，已拒绝继续操作。\\n` +\n        `当前可见窗口：\\n${candidates || '无'}`,\n    }\n  }\n  if (!target) {\n    const sorted = [...windows].sort((a, b) => (b.z_index || 0) - (a.z_index || 0))\n    target = sorted[0]\n  }\n\n  // 3. AX 树（vision / native 模式同时抓截图）\n  const needShot = wantMode === 'vision' || wantMode === 'native'\n  const gwArgs = {\n    pid: target.pid,\n    window_id: target.window_id,\n    include_screenshot: needShot,\n    max_elements: maxElements,\n  }\n  if (args.query) gwArgs.query = String(args.query)\n  let state = await cuaCall('get_window_state', withSession(gwArgs))\n  const rawElements = Array.isArray(state.elements) ? state.elements : []\n  const elements = rawElements.filter(isActionable)\n  // 截图缺失（首次 ax 调用后才降级）→ 补抓\n  const needShotNow = needShot || (wantMode !== 'vision' && wantMode !== 'native'\n    && (Boolean(state.degraded_reason) || rawElements.length === 0) && (await routeImageCapable(ctx, exec) || glmVisionConfigured()))\n  if (needShotNow && !state.screenshot_png_b64) {\n    const v = await cuaCall('get_window_state', withSession({\n      pid: target.pid,\n      window_id: target.window_id,\n      include_screenshot: true,\n      max_elements: maxElements,\n    }))\n    state = { ...state, ...v }\n  }\n\n  // 4. 模式决策\n  const degraded = Boolean(state.degraded_reason) || rawElements.length === 0\n  let effectiveMode = 'ax'\n  let visionText = ''\n  let image = null\n\n  if (wantMode === 'native') {\n    const capable = await routeImageCapable(ctx, exec)\n    if (!capable) {\n      const { provider, model } = { provider: exec?.agent?.options?.provider, model: exec?.agent?.options?.model }\n      return {\n        ok: false,\n        result: `原生视觉模式（mode=\"native\"）需要当前对话模型支持图片输入，但当前 route ${provider}/${model} 未声明 image 能力。`\n          + '请切换到视觉模型（如 deepseek-v4-flash-vision-exp），或使用 mode=\"vision\"（观察者）/ mode=\"ax\"。',\n      }\n    }\n    try {\n      const { ref, width, height, compact } = await commitScreenshot(ctx, target, state, cfg)\n      image = {\n        attachmentId: ref.attachmentId,\n        mediaType: ref.mediaType,\n        bytes: ref.bytes,\n        width: ref.width ?? width,\n        height: ref.height ?? height,\n        name: ref.name,\n      }\n      effectiveMode = 'native'\n      visionText = compact\n        ? '（紧凑图：原始截图超附件限额，已用引擎 zoom 降采样为 ≤500px JPEG）'\n        : ''\n    } catch (err) {\n      return { ok: false, result: `原生截图失败：${err.message}` }\n    }\n  } else if (wantMode === 'vision') {\n    visionText = await describeVision(ctx, cfg, state, target, exec)\n    effectiveMode = 'vision'\n  } else { // ax 默认\n    if (degraded) {\n      if (await routeImageCapable(ctx, exec)) {\n        try {\n          const { ref, width, height } = await commitScreenshot(ctx, target, state, cfg)\n          image = { attachmentId: ref.attachmentId, mediaType: ref.mediaType, bytes: ref.bytes, width: ref.width ?? width, height: ref.height ?? height, name: ref.name }\n          effectiveMode = 'native'\n        } catch {\n          effectiveMode = 'ax'\n        }\n      } else if (glmVisionConfigured()) {\n        visionText = await describeVision(ctx, cfg, state, target, exec)\n        effectiveMode = 'vision'\n      }\n    }\n  }\n\n  // 5. 快照缓存（element_token 自带的 snapshot_id 由引擎校验）\n  const entries = new Map()\n  for (const e of elements) {\n    const c = centerOf(e)\n    entries.set(e.element_index, {\n      token: e.element_token,\n      role: safeStr(e.role, 40),\n      label: safeStr(e.label || e.value || '', 100),\n      x: c ? c.x : null,\n      y: c ? c.y : null,\n    })\n  }\n  setSnapshot({\n    at: Date.now(),\n    ttlMs: cfg.ttlMs,\n    pid: target.pid,\n    windowId: target.window_id,\n    appName: target.app_name || '',\n    snapshotId: state.snapshot_id,\n    entries,\n    elementCount: state.element_count,\n    totalElementCount: state.total_element_count,\n    mode: effectiveMode,\n    screenshotWidth: state.screenshot_width || null,\n    screenshotHeight: state.screenshot_height || null,\n  })\n\n  // 6. 渲染\n  const lines = elements.map(renderLine)\n  let modeNote = `模式=${effectiveMode}`\n  if (effectiveMode === 'vision') {\n    modeNote += degraded && wantMode !== 'vision' ? '（AX 树为空自动降级）' : ''\n  } else if (effectiveMode === 'native') {\n    modeNote += degraded && wantMode !== 'native' ? '（AX 树为空自动降级）' : ''\n  }\n  const header = [\n    `窗口: ${safeStr(target.app_name)} · ${safeStr(target.title)}`,\n    `pid=${target.pid} window_id=${target.window_id} ${modeNote} 坐标=窗口本地截图像素`,\n    effectiveMode === 'ax'\n      ? `可见元素 ${lines.length} 个（树共 ${state.element_count}/${state.total_element_count}，快照 ${state.snapshot_id}）`\n      : effectiveMode === 'native'\n        ? `AX 元素 ${lines.length} 个，原生直读截图如下 ${visionText}`\n        : `AX 元素 ${lines.length} 个，视觉描述如下`,\n  ].join('\\n')\n\n  const body = lines.length > 0\n    ? lines.join('\\n')\n    : effectiveMode === 'native'\n      ? '(AX 树无可用元素 —— 请直接看图，用截图坐标点击)'\n      : '(AX 树无可用元素)'\n\n  const visionBlock = visionText && effectiveMode === 'vision' ? `\\n── 视觉理解 ──\\n${visionText}` : ''\n\n  return buildObserveOutput({\n    ok: true,\n    result: `${header}\\n${body}${visionBlock}\\n\\n提示: 用 computer_click(element=[编号]) 或 computer_click(x=, y=) 操作（坐标为截图像素）。`,\n    window: { pid: target.pid, windowId: target.window_id, app: safeStr(target.app_name, 60), title: safeStr(target.title, 80) },\n    elementCount: elements.length,\n    mode: effectiveMode,\n    elements: elements.map((e) => {\n      const c = centerOf(e)\n      return {\n        index: e.element_index,\n        role: safeStr(shortRole(e.role), 40),\n        label: safeStr(e.label || e.value || '', 100),\n        x: c ? c.x : null,\n        y: c ? c.y : null,\n      }\n    }),\n    screenshotFile: state.screenshot_out_file || null,\n    image,\n  })\n}\n\n/** Assemble the schema-facing output without serializing an absent image as null. */\nexport function buildObserveOutput({ image, ...value }) {\n  return image ? { ...value, image } : value\n}\n\n/**\n * screen_zoom —— 区域截图工具：裁剪窗口某区域（截图像素）为 ≤500px JPEG 直读。\n * 用于\"放大某块区域细看\"：图片 token 远小于整窗截图。\n * @param {object} ctx\n * @param {object} args - { window?, x1, y1, x2, y2, question? }\n */\nexport async function screenZoom(ctx, args, cfg, exec) {\n  const capable = await routeImageCapable(ctx, exec)\n  if (!capable) {\n    return { ok: false, result: 'screen_zoom 需要当前对话模型支持图片输入（原生直读），请使用视觉模型（如 deepseek-v4-flash-vision-exp）。' }\n  }\n  // pid 缺省时按 window_id 从窗口表解析（引擎 zoom 需要 pid）\n  let pid = args.pid\n  if (!pid) {\n    const winList = await cuaCall('list_windows', { on_screen_only: true })\n    const hit = (winList.windows || []).find((w) => Number(w.window_id) === Number(args.window_id))\n    if (!hit) return { ok: false, result: `window_id ${args.window_id} 不在当前可见窗口列表中。` }\n    pid = hit.pid\n  }\n  const size = await cuaCall('get_window_state', withSession({\n    pid,\n    window_id: args.window_id,\n    include_screenshot: true,\n    max_elements: 1,\n  }))\n  const w = size?.screenshot_width || 1\n  const h = size?.screenshot_height || 1\n  const x1 = args.x1 ?? 0\n  const y1 = args.y1 ?? 0\n  const x2 = args.x2 ?? w\n  const y2 = args.y2 ?? h\n  const attachments = ctx?.get?.('attachments')\n  if (!attachments) return { ok: false, result: '当前环境未挂载 attachments 服务。' }\n  const zv = await cuaCall('zoom', withSession({\n    pid,\n    window_id: args.window_id,\n    x1: Math.max(0, Number(x1)),\n    y1: Math.max(0, Number(y1)),\n    x2: Math.max(1, Math.min(w, Number(x2))),\n    y2: Math.max(1, Math.min(h, Number(y2))),\n  }))\n  const jpeg = buf(zv?.screenshot_png_b64)\n  if (jpeg.byteLength === 0) return { ok: false, result: 'zoom 返回空图片。' }\n  const ref = await attachments.saveImage({\n    data: jpeg,\n    mediaType: 'image/jpeg',\n    name: `screen-zoom-${args.window_id}.jpg`,\n  })\n  const image = {\n    attachmentId: ref.attachmentId,\n    mediaType: ref.mediaType,\n    bytes: ref.bytes,\n    width: ref.width ?? zv?.width,\n    height: ref.height ?? zv?.height,\n    name: ref.name,\n  }\n  return {\n    ok: true,\n    result: `区域截图完成（${image.width}×${image.height}px JPEG）：坐标为窗口本地截图像素，点击时直接传截图坐标。`,\n    image,\n  }\n}\n"
